    /// CREATE TABLE CHILD(ID INT PRIMARY KEY, P INT);
    /// ALTER TABLE CHILD ADD FOREIGN KEY(P) REFERENCES PARENT(K) ON DELETE SET NULL;
    /// </code>
    /// </summary>
    public const int GeneratedColumnCannotBeUpdatableByConstraint2 = 90155;

    /// <summary>
    /// The error with code <code>90156</code> is thrown when trying to create a
    /// view or a table from a select and some expression doesn't have a column
    /// name or alias when it is required by a compatibility mode.
    ///
    /// <code>
    /// SET MODE DB2;
    /// CREATE TABLE T1(A INT, B INT);
    /// CREATE TABLE T2 AS (SELECT A + B FROM T1) WITH DATA;
    /// </code>
    /// </summary>
    public const int ColumnAliasIsNotSpecified1 = 90156;

    /// <summary>
    /// The error with code <code>90157</code> is thrown when the integer
    /// index that is used in the GROUP BY is not in the SELECT list
    /// </summary>
    public const int GroupByNotInTheResult = 90157;

    /// <summary>
    /// INTERNAL
    /// </summary>
    /// <param name="errorCode">to check</param>
    /// <returns>true if provided code is common, false otherwise</returns>
    public static bool IsCommon(int errorCode)
    {
        // this list is sorted alphabetically
        switch (errorCode)
        {
            case DataConversionError1:
            case DuplicateKey1:
            case FunctionAliasAlreadyExists1:
            case LockTimeout1:
            case NullNotAllowed:
            case NoDataAvailable:
            case NumericValueOutOfRange1:
            case ObjectClosed:
            case ReferentialIntegrityViolatedChildExists1:
            case ReferentialIntegrityViolatedParentMissing1:
            case SyntaxError1:
            case SyntaxError2:
            case TableOrViewAlreadyExists1:
            case TableOrViewNotFound1:
            case TableOrViewNotFoundWithCandidates2:
            case TableOrViewNotFoundDatabaseEmpty1:
            case ValueTooLong2:
                return true;
            default:
                return false;
        }
    }

    /// <summary>
    /// Returns the SQLSTATE string for the given error code.
    /// </summary>
    /// <param name="errorCode">to get state for</param>
    /// <returns>error state</returns>
    public static string GetState(int errorCode)
    {
        // To convert SQLState to error code, replace
        // 21S: 210, 42S: 421, HY: 50, C: 1, T: 2
        switch (errorCode)
        {
            // 02: no data
            case NoDataAvailable:
                return "02000";

            // 07: dynamic SQL error
            case InvalidParameterCount2:
                return "07001";

            // 08: connection exception
            case ErrorOpeningDatabase1:
                return "08000";

            // 21: cardinality violation
            case ColumnCountDoesNotMatch:
                return "21S02";

            // 22: data exception
            case NullValueInArrayTarget:
                return "2200E";
            case ArrayElementError2:
                return "2202E";

            // 42: syntax error or access rule violation
            case TableOrViewAlreadyExists1:
                return "42S01";
            case TableOrViewNotFound1:
                return "42S02";
            case TableOrViewNotFoundWithCandidates2:
                return "42S03";
            case TableOrViewNotFoundDatabaseEmpty1:
                return "42S04";
            case IndexAlreadyExists1:
                return "42S11";
            case IndexNotFound1:
                return "42S12";
            case DuplicateColumnName1:
                return "42S21";
            case ColumnNotFound1:
                return "42S22";
            case DuplicateTableAlias1:
                return "42S23";
            case IdenticalExpressionsShouldBeUsed:
                return "42S31";

            // 0A: feature not supported

            // HZ: remote database access

            // HY
            case GeneralError1:
                return "HY000";
            case UnknownDataType1:
                return "HY004";

            case FeatureNotSupported1:
                return "HYC00";
            case LockTimeout1:
                return "HYT00";
            default:
                return errorCode.ToString(System.Globalization.CultureInfo.InvariantCulture);
        }
    }
}
